1	import Link from "next/link";
2	import { GAME_ART_SLUG, GAME_DISPLAY, type GameFamily } from "@/lib/games";
3	import { getPosterAccentColor } from "@/lib/game-poster-color";
4	
5	/**
6	 * The NxLabs homepage's real "game catalogue" — every real family
7	 * `listCatalogFamilies()` returns (already the FULL set, not a "popular"
8	 * subset — see PopularGamesStrip.tsx's own comment, it renders the same
9	 * complete list at a compact size for the dashboard's tighter layout). This
10	 * is a bigger, more premium presentation of that same real data for the
11	 * marketing homepage specifically: full portrait box art (not a cropped
12	 * 4:3 thumbnail), a per-game accent ring genuinely sampled from that game's
13	 * own art (lib/game-poster-color.ts — same real-pixel method GameBadge
14	 * uses, never a hand-picked hex), and an explicit "Browse mods" reveal on
15	 * hover/focus so this reads as the catalogue's own front door rather than a
16	 * strip of tiles above the fold.
17	 *
18	 * Async Server Component: the accent-color sample is a cached, network-free
19	 * disk read (see getPosterAccentColor's own header comment), so resolving it
20	 * for every family up front costs nothing after the first render.
21	 */
22	export async function GameCatalogueGrid({
23	  families,
24	  hrefFor,
25	}: {
26	  families: { family: string; label: string; count: number }[];
27	  hrefFor: (family: string) => string;
28	}) {
29	  const accents = await Promise.all(families.map((f) => getPosterAccentColor(f.family)));
30	
31	  return (
32	    <div className="grid grid-cols-2 gap-4 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6">
33	      {families.map((f, i) => {
34	        const poster = GAME_ART_SLUG[f.family as GameFamily]?.poster ?? GAME_ART_SLUG[f.family as GameFamily]?.hero;
35	        const accent = accents[i];
36	        const name = GAME_DISPLAY[f.family as GameFamily]?.name ?? f.label;
37	        return (
38	          <Link
39	            key={f.family}
40	            href={hrefFor(f.family)}
41	            className="group relative flex flex-col overflow-hidden rounded-2xl border border-white/10 bg-white/[0.02] transition-all duration-200 hover:-translate-y-1"
42	          >
43	            <div className="relative aspect-[3/4] w-full overflow-hidden bg-white/[0.04]">
44	              {poster ? (
45	                // eslint-disable-next-line @next/next/no-img-element
46	                <img
47	                  src={`/games/art/${poster}_poster.jpg`}
48	                  alt={name}
49	                  loading="lazy"
50	                  className="h-full w-full object-cover transition-transform duration-300 group-hover:scale-[1.06]"
51	                />
52	              ) : (
53	                <div className="flex h-full w-full items-center justify-center text-3xl">🎮</div>
54	              )}
55	              {/* accent-colored ring, revealed on hover — genuinely sampled per game (inline
56	                  box-shadow, not Tailwind's `ring-*` utility, so this doesn't depend on
57	                  Tailwind's internal --tw-ring-color implementation detail). */}
58	              <div
59	                className="pointer-events-none absolute inset-0 rounded-2xl opacity-0 transition-opacity duration-200 group-hover:opacity-100"
60	                style={{ boxShadow: `inset 0 0 0 2px ${accent}` }}
61	                aria-hidden
62	              />
63	              <div className="pointer-events-none absolute inset-x-0 bottom-0 h-2/3 bg-gradient-to-t from-black/90 to-transparent" />
64	              {/* "Browse mods" reveal — the catalogue framing, not just a poster wall */}
65	              <div className="pointer-events-none absolute inset-0 flex items-end justify-center pb-3 opacity-0 transition-opacity duration-200 group-hover:opacity-100">
66	                <span
67	                  className="rounded-full px-3 py-1 text-[11px] font-semibold uppercase tracking-wide text-white"
68	                  style={{ background: accent }}
69	                >
70	                  Browse mods →
71	                </span>
72	              </div>
73	            </div>
74	            <div className="p-3">
75	              <p className="truncate text-sm font-semibold text-white">{name}</p>
76	              <p className="text-[11px] text-slate-400">{f.count.toLocaleString()} mods</p>
77	            </div>
78	          </Link>
79	        );
80	      })}
81	    </div>
82	  );
83	}
