25	/** One DB-fed price tier for a game (subset of db.gamePlan). */
26	export type ShowcaseTier = {
27	  /** Real GamePlan.id — lets a Deploy button target this exact tier instead of
28	   *  a nearest-fit-by-slots guess (see lib/deploy-intent.ts, GameConfigurator). */
29	  id: string;
30	  name: string;
31	  ramMB: number;
32	  cpuCores: number;
33	  diskGB: number;
34	  slots: number | null;
