111	
112	      {/* Selected-tier detail — every figure below is straight from the DB tier. */}
113	      <div key={sel} className="mt-3 motion-safe:animate-[var(--animate-price-pop)]">
114	        <div className="flex items-end justify-between gap-3">
115	          <div>
116	            <p className="text-[11px] uppercase tracking-wide text-slate-500">Starting at</p>
117	            <p className="text-3xl font-extrabold tracking-tight text-white">
118	              {money(tier.priceCents)}
119	              <span className="ml-1 text-sm font-normal text-slate-400">{per(tier.termMonths)}</span>
