128	        <ul className="mt-3 grid grid-cols-2 gap-x-3 gap-y-1.5 text-xs text-slate-300">
129	          <li className="flex items-center gap-1.5">
130	            <IconBolt size={13} className="text-brand-300" /> {gb(tier.ramMB)} RAM
131	          </li>
132	          <li className="flex items-center gap-1.5">
133	            <IconBolt size={13} className="text-brand-300" /> {tier.cpuCores} vCPU
134	          </li>
135	          <li className="flex items-center gap-1.5">
136	            <IconBolt size={13} className="text-brand-300" /> {tier.diskGB} GB NVMe
137	          </li>
138	          <li className="flex items-center gap-1.5">
139	            <IconBolt size={13} className="text-brand-300" /> DDoS protected
140	          </li>
141	        </ul>
142	      </div>
143	
144	      <Link href="#pricing" className="btn-primary mt-4 w-full text-center">
