237	export function GameCoverCarousel({ games }: { games: ShowcaseGame[] }) {
238	  const n = games.length;
239	  // Start on the first "Popular" title, else the second card for a coverflow feel.
240	  const initial = (() => {
241	    const f = games.findIndex((g) => g.tiers.some((t) => t.featured));
242	    return f >= 0 ? f : Math.min(1, Math.max(0, n - 1));
243	  })();
244	
245	  const [active, setActive] = useState(initial);
246	  const [ready, setReady] = useState(false);
247	  const [paused, setPaused] = useState(false);
248	
249	  const viewportRef = useRef<HTMLDivElement>(null);
250	  const trackRef = useRef<HTMLDivElement>(null);
251	  const cardRefs = useRef<(HTMLDivElement | null)[]>([]);
252	
253	  const offsetRef = useRef(initial); // live fractional position (in card-units)
254	  const targetRef = useRef(initial);
255	  const rafRef = useRef<number | null>(null);
256	  const reducedRef = useRef(false);
257	  const activeRef = useRef(initial); // mirror for handlers without re-subscribing
258	
259	  const clamp = useCallback((i: number) => Math.max(0, Math.min(n - 1, i)), [n]);
260	
261	  /* Paint one frame: track translate + per-card depth, from offsetRef. */
262	  const paint = useCallback(() => {
263	    const vp = viewportRef.current;
264	    const track = trackRef.current;
265	    const first = cardRefs.current[0];
266	    const second = cardRefs.current[1];
267	    if (!vp || !track || !first) return;
268	
269	    const cardW = first.offsetWidth;
270	    const step = second ? second.offsetLeft - first.offsetLeft : cardW;
271	    const base = first.offsetLeft + cardW / 2; // center of card 0 within the track
272	    const vpCenter = vp.clientWidth / 2;
273	    const off = offsetRef.current;
274	
275	    track.style.transform = `translate3d(${vpCenter - base - off * step}px,0,0)`;
276	
277	    const cards = cardRefs.current;
278	    for (let i = 0; i < cards.length; i++) {
279	      const el = cards[i];
280	      if (!el) continue;
281	      const d = i - off; // signed distance from center, in cards
282	      const a = Math.min(Math.abs(d), 1.6);
283	      const scale = 1.08 - a * 0.19; // center pops, neighbours recede
284	      const lift = a * 14; // side cards drop slightly
285	      const rot = Math.max(-1, Math.min(1, d)) * -5; // faint coverflow tilt
286	      const opacity = 1 - Math.min(a, 1) * 0.5;
287	      el.style.transform = `translateY(${lift}px) scale(${scale}) perspective(1000px) rotateY(${rot}deg)`;
288	      el.style.opacity = `${opacity}`;
289	      el.style.zIndex = `${100 - Math.round(a * 10)}`;
290	    }
291	  }, []);
292	
293	  /* Spring toward targetRef; commit `active` when it settles. */
294	  const animate = useCallback(() => {
295	    const diff = targetRef.current - offsetRef.current;
296	    if (Math.abs(diff) < 0.0015) {
297	      offsetRef.current = targetRef.current;
298	      paint();
299	      rafRef.current = null;
300	      const idx = clamp(Math.round(offsetRef.current));
301	      activeRef.current = idx;
302	      setActive(idx);
303	      return;
304	    }
305	    offsetRef.current += diff * 0.185;
306	    paint();
307	    rafRef.current = requestAnimationFrame(animate);
308	  }, [paint, clamp]);
309	
310	  /* Settle onto a target card (instant when reduced-motion). */
311	  const settleTo = useCallback(
312	    (target: number) => {
313	      targetRef.current = clamp(target);
314	      if (reducedRef.current) {
315	        offsetRef.current = targetRef.current;
316	        paint();
317	        const idx = clamp(Math.round(targetRef.current));
318	        activeRef.current = idx;
319	        setActive(idx);
320	        return;
321	      }
322	      if (rafRef.current == null) rafRef.current = requestAnimationFrame(animate);
323	    },
324	    [animate, paint, clamp],
325	  );
326	
327	  const go = useCallback((i: number) => settleTo(i), [settleTo]);
328	
329	  /* ── mount: detect reduced-motion, first layout, resize + fade-in ──────────── */
330	  useIsoLayoutEffect(() => {
331	    reducedRef.current =
332	      typeof window !== "undefined" &&
333	      window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
334	    paint();
335	    setReady(true);
336	    const onResize = () => paint();
337	    window.addEventListener("resize", onResize);
338	    return () => {
339	      window.removeEventListener("resize", onResize);
340	      if (rafRef.current != null) cancelAnimationFrame(rafRef.current);
341	    };
342	    // paint is stable; run once on mount.
343	    // eslint-disable-next-line react-hooks/exhaustive-deps
344	  }, []);
345	
346	  /* ── pointer / touch momentum drag ─────────────────────────────────────────── */
347	  useEffect(() => {
348	    const vp = viewportRef.current;
349	    const track = trackRef.current;
350	    const first = cardRefs.current[0];
351	    const second = cardRefs.current[1];
352	    if (!vp || !track) return;
353	
354	    let dragging = false;
355	    let moved = false;
356	    let startX = 0;
357	    let startOffset = 0;
358	    let lastX = 0;
359	    let lastT = 0;
360	    let velocity = 0; // card-units per ms
361	    let step = second && first ? second.offsetLeft - first.offsetLeft : first?.offsetWidth || 1;
362	
363	    const onDown = (e: PointerEvent) => {
364	      if (e.button != null && e.button !== 0) return;
365	      // Never start a drag from an interactive control inside the active card
366	      // (the player-slot buttons) — this listener is a plain native
367	      // addEventListener on `vp`, so it fires during the REAL DOM bubble
368	      // phase, before React's root-delegated synthetic handlers ever run.
369	      // The button's own onPointerDown/onClick stopPropagation() therefore
370	      // cannot stop it — by the time React gets to call stopPropagation(),
371	      // this handler has already grabbed pointer capture and started
372	      // dragging, which is why the slot buttons were unclickable.
373	      if ((e.target as HTMLElement)?.closest("button")) return;
374	      const f = cardRefs.current[0];
375	      const s = cardRefs.current[1];
376	      step = s && f ? s.offsetLeft - f.offsetLeft : f?.offsetWidth || step;
377	      dragging = true;
378	      moved = false;
379	      startX = lastX = e.clientX;
380	      startOffset = offsetRef.current;
381	      lastT = e.timeStamp;
382	      velocity = 0;
383	      if (rafRef.current != null) {
384	        cancelAnimationFrame(rafRef.current);
385	        rafRef.current = null;
386	      }
387	      setPaused(true);
388	      track.style.transition = "none";
389	      vp.setPointerCapture?.(e.pointerId);
390	    };
391	
392	    const onMove = (e: PointerEvent) => {
393	      if (!dragging) return;
394	      const dx = e.clientX - startX;
395	      if (Math.abs(dx) > 4) moved = true;
396	      offsetRef.current = clamp(startOffset - dx / step);
397	      const dt = e.timeStamp - lastT || 16;
398	      velocity = -(e.clientX - lastX) / step / dt;
399	      lastX = e.clientX;
400	      lastT = e.timeStamp;
401	      paint();
402	    };
403	
404	    const onUp = (e: PointerEvent) => {
405	      if (!dragging) return;
406	      dragging = false;
407	      vp.releasePointerCapture?.(e.pointerId);
408	      // Fold flick velocity into how many cards we travel, then snap.
409	      const flick = Math.max(-MAX_FLICK, Math.min(MAX_FLICK, velocity * 1000 * MOMENTUM));
410	      const target = clamp(Math.round(offsetRef.current + flick));
411	      settleTo(target);
412	      // Suppress the click that follows a real drag.
413	      if (moved) {
414	        const stop = (ev: Event) => {
415	          ev.stopPropagation();
416	          ev.preventDefault();
417	        };
418	        vp.addEventListener("click", stop, { capture: true, once: true });
419	      }
420	    };
421	
422	    vp.addEventListener("pointerdown", onDown);
423	    window.addEventListener("pointermove", onMove);
424	    window.addEventListener("pointerup", onUp);
425	    window.addEventListener("pointercancel", onUp);
426	    return () => {
427	      vp.removeEventListener("pointerdown", onDown);
428	      window.removeEventListener("pointermove", onMove);
429	      window.removeEventListener("pointerup", onUp);
430	      window.removeEventListener("pointercancel", onUp);
431	    };
432	  }, [clamp, paint, settleTo]);
433	
434	  /* ── trackpad / wheel (horizontal intent only) ─────────────────────────────── */
435	  useEffect(() => {
436	    const vp = viewportRef.current;
437	    if (!vp) return;
438	    let lock = 0;
439	    const onWheel = (e: WheelEvent) => {
440	      const horizontal = Math.abs(e.deltaX) > Math.abs(e.deltaY);
441	      if (!horizontal) return; // never hijack vertical page scroll
442	      e.preventDefault();
443	      const now = e.timeStamp;
444	      if (now - lock < 260) return;
445	      lock = now;
446	      settleTo(clamp(Math.round(targetRef.current) + (e.deltaX > 0 ? 1 : -1)));
447	    };
448	    vp.addEventListener("wheel", onWheel, { passive: false });
449	    return () => vp.removeEventListener("wheel", onWheel);
450	  }, [clamp, settleTo]);
451	
452	  /* ── autoplay (pauses on hover/focus/drag/hidden/reduced-motion) ───────────── */
453	  useEffect(() => {
454	    if (paused || reducedRef.current || n <= 1) return;
455	    const id = window.setInterval(() => {
456	      if (document.hidden) return;
457	      const next = activeRef.current + 1 >= n ? 0 : activeRef.current + 1;
458	      settleTo(next);
459	    }, 4200);
460	    return () => window.clearInterval(id);
461	  }, [paused, n, settleTo]);
462	
463	  if (n === 0) return null;
464	
465	  const onKeyDown = (e: React.KeyboardEvent) => {
466	    if (e.key === "ArrowLeft") {
467	      e.preventDefault();
468	      go(activeRef.current - 1);
469	    } else if (e.key === "ArrowRight") {
470	      e.preventDefault();
471	      go(activeRef.current + 1);
472	    } else if (e.key === "Home") {
473	      e.preventDefault();
474	      go(0);
475	    } else if (e.key === "End") {
476	      e.preventDefault();
477	      go(n - 1);
478	    }
479	  };
480	
481	  return (
482	    <div
483	      className="relative min-w-0"
484	      onMouseEnter={() => setPaused(true)}
485	      onMouseLeave={() => setPaused(false)}
486	      onFocusCapture={() => setPaused(true)}
487	      onBlurCapture={() => setPaused(false)}
488	    >
489	      <HeroBackdrop family={games[active]?.family ?? ""} />
490	      <div className="pointer-events-none absolute -inset-x-16 -inset-y-24 -z-10 overflow-hidden sm:-inset-x-24">
491	        <GameParticleField
492	          colorFrom={(GAME_VISUAL[games[active]?.family ?? ""] ?? NEUTRAL).from}
493	          colorTo={(GAME_VISUAL[games[active]?.family ?? ""] ?? NEUTRAL).to}
494	          triggerKey={games[active]?.family ?? active}
495	        />
496	      </div>
497	
498	      {/* Arrow controls (pointer devices; swipe on touch). */}
499	      <div className="pointer-events-none absolute inset-y-0 left-0 right-0 z-40 hidden items-center justify-between sm:flex">
500	        <button
501	          type="button"
502	          aria-label="Previous game"
503	          onClick={() => go(active - 1)}
504	          disabled={active === 0}
505	          className="pointer-events-auto -ml-3 grid h-11 w-11 place-items-center rounded-full border border-white/10 bg-navy-950/80 text-slate-200 backdrop-blur transition hover:border-brand-500/50 hover:text-white disabled:opacity-25 lg:-ml-5"
506	        >
507	          <span className="rotate-180">
508	            <IconArrow size={18} />
509	          </span>
510	        </button>
511	        <button
512	          type="button"
513	          aria-label="Next game"
514	          onClick={() => go(active + 1)}
515	          disabled={active === n - 1}
516	          className="pointer-events-auto -mr-3 grid h-11 w-11 place-items-center rounded-full border border-white/10 bg-navy-950/80 text-slate-200 backdrop-blur transition hover:border-brand-500/50 hover:text-white disabled:opacity-25 lg:-mr-5"
517	        >
518	          <IconArrow size={18} />
519	        </button>
520	      </div>
521	
522	      {/* Viewport — clips horizontally only. The active card's box-shadow glow
523	          has an 80px blur radius; `overflow-hidden` here used to clip that
524	          glow top/bottom too (no amount of vertical padding fully contains an
525	          80px blur), which is what read as a hard-edged rectangle behind the
526	          carousel instead of a soft halo. overflow-x-hidden keeps side cards
527	          from spilling onto the rest of the page while letting the glow's
528	          paint (which doesn't affect layout height) bleed past the box
529	          vertically, same as HeroBackdrop already does above. */}
530	      <div
531	        ref={viewportRef}
532	        role="group"
533	        aria-roledescription="carousel"
