538	        style={{ cursor: "grab" }}
539	      >
540	        <div
541	          ref={trackRef}
542	          className="flex w-max items-center gap-4 will-change-transform"
543	          style={{ opacity: ready ? 1 : 0, transition: "opacity .4s ease" }}
544	        >
545	          {games.map((g, i) => {
