"use client";

/**
 * The interactive half of the marketing /mods homepage's game catalogue —
 * split out of GameCatalogueGrid.tsx (a Server Component, which does the
 * real per-game accent-color sampling) because search + carousel state both
 * need client JS. This component receives fully-resolved, already-real data
 * (name, poster, accent, href — no placeholders) and only handles two
 * interactions:
 *
 *   1. A live client-side search over these exact ~17 families — no
 *      round-trip, since the whole list is already in hand and this small a
 *      set never needs pagination (contrast StoreBrowser.tsx's own
 *      server-side search, which exists precisely because the general mod
 *      catalog is 30k+ rows and can't live in the client at once).
 *   2. A single-row sliding carousel instead of the old wrapping grid —
 *      plain CSS scroll-snap (`overflow-x-auto` + `snap-x`) rather than a
 *      new dependency: this codebase has no carousel library (checked
 *      package.json) and already ships this exact pattern for
 *      GameShowcaseCarousel.tsx's hero row. Native scroll-snap gives real
 *      touch/trackpad swipe for free; the arrow buttons and a light
 *      pointer-drag handler (mouse users with neither) are added on top.
 */

import { useMemo, useRef, useState } from "react";
import Link from "next/link";
import { IconArrow, IconSearch } from "./icons";

export type CatalogueItem = {
  family: string;
  name: string;
  count: number;
  poster?: string;
  accent: string;
  href: string;
};

function prefersReducedMotion() {
  return typeof window !== "undefined" && window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
}

export function GameCatalogueCarousel({ items }: { items: CatalogueItem[] }) {
  const [query, setQuery] = useState("");
  const trackRef = useRef<HTMLDivElement>(null);

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return items;
    return items.filter((it) => it.name.toLowerCase().includes(q));
  }, [items, query]);

  function scrollByCard(dir: 1 | -1) {
    const track = trackRef.current;
    if (!track) return;
    const card = track.querySelector<HTMLElement>("[data-card]");
    const step = card ? card.offsetWidth + 16 /* gap-4 */ : track.clientWidth * 0.8;
    track.scrollBy({ left: dir * step, behavior: prefersReducedMotion() ? "auto" : "smooth" });
  }

  // Lightweight drag-to-scroll for desktop mouse users (touch/trackpad already
  // get real native scrolling from `overflow-x-auto` + `snap-x` with no JS at
  // all). Only counts as a "drag" past a small pixel threshold, and when it
  // does, the click that would otherwise follow (and navigate a card's Link)
  // is swallowed once — same guard GameCoverCarousel.tsx uses for its own
  // momentum drag, just without the velocity/spring machinery this static
  // catalogue row doesn't need.
  const drag = useRef<{ startX: number; startScroll: number; moved: boolean } | null>(null);

  function onPointerDown(e: React.PointerEvent<HTMLDivElement>) {
    if (e.pointerType === "touch") return;
    const track = trackRef.current;
    if (!track) return;
    drag.current = { startX: e.clientX, startScroll: track.scrollLeft, moved: false };
    track.setPointerCapture(e.pointerId);
  }
  function onPointerMove(e: React.PointerEvent<HTMLDivElement>) {
    const st = drag.current;
    const track = trackRef.current;
    if (!st || !track) return;
    const dx = e.clientX - st.startX;
    if (Math.abs(dx) > 3) st.moved = true;
    track.scrollLeft = st.startScroll - dx;
  }
  function onPointerUp(e: React.PointerEvent<HTMLDivElement>) {
    const st = drag.current;
    const track = trackRef.current;
    if (st?.moved && track) {
      const stop = (ev: Event) => {
        ev.preventDefault();
        ev.stopPropagation();
      };
      track.addEventListener("click", stop, { capture: true, once: true });
    }
    drag.current = null;
    track?.releasePointerCapture?.(e.pointerId);
  }

  return (
    <div>
      <div className="relative mb-6 max-w-sm">
        <IconSearch
          className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-[var(--fg-muted)]"
          size={16}
        />
        <input
          type="search"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          placeholder="Search games…"
          aria-label="Search games"
          className="input w-full pl-9 text-sm"
        />
      </div>

      {filtered.length === 0 ? (
        <p className="rounded-2xl border border-white/10 bg-white/[0.02] px-6 py-10 text-center text-sm text-slate-400">
          No games match &ldquo;{query}&rdquo;.
        </p>
      ) : (
        <div className="relative">
          {/* Arrow controls — hidden on touch-first small screens (swipe instead),
              same treatment as GameShowcaseCarousel's own hero row. */}
          <div className="pointer-events-none absolute inset-y-0 left-0 right-0 z-20 hidden items-center justify-between sm:flex">
            <button
              type="button"
              aria-label="Scroll games left"
              onClick={() => scrollByCard(-1)}
              className="pointer-events-auto -ml-3 grid h-10 w-10 place-items-center rounded-full border border-white/10 bg-navy-900/80 text-slate-200 backdrop-blur transition hover:border-brand-500/40 hover:text-white lg:-ml-5"
            >
              <span className="rotate-180">
                <IconArrow size={18} />
              </span>
            </button>
            <button
              type="button"
              aria-label="Scroll games right"
              onClick={() => scrollByCard(1)}
              className="pointer-events-auto -mr-3 grid h-10 w-10 place-items-center rounded-full border border-white/10 bg-navy-900/80 text-slate-200 backdrop-blur transition hover:border-brand-500/40 hover:text-white lg:-mr-5"
            >
              <IconArrow size={18} />
            </button>
          </div>

          <div
            ref={trackRef}
            onPointerDown={onPointerDown}
            onPointerMove={onPointerMove}
            onPointerUp={onPointerUp}
            onPointerCancel={onPointerUp}
            className="flex snap-x snap-mandatory gap-4 overflow-x-auto scroll-smooth pb-4 pt-1 [scrollbar-width:none] motion-reduce:scroll-auto [&::-webkit-scrollbar]:hidden"
            style={{ cursor: "grab" }}
          >
            {filtered.map((it) => (
              <Link
                key={it.family}
                data-card
                href={it.href}
                draggable={false}
                className="group relative flex w-36 shrink-0 snap-start flex-col overflow-hidden rounded-2xl border border-white/10 bg-white/[0.02] transition-all duration-200 hover:-translate-y-1 sm:w-44 lg:w-48"
              >
                <div className="relative aspect-[3/4] w-full overflow-hidden bg-white/[0.04]">
                  {it.poster ? (
                    // eslint-disable-next-line @next/next/no-img-element
                    <img
                      src={`/games/art/${it.poster}_poster.jpg`}
                      alt={it.name}
                      loading="lazy"
                      draggable={false}
                      className="h-full w-full object-cover transition-transform duration-300 group-hover:scale-[1.06]"
                    />
                  ) : (
                    <div className="flex h-full w-full items-center justify-center text-3xl">🎮</div>
                  )}
                  {/* accent-colored ring, revealed on hover — genuinely sampled per game (inline
                      box-shadow, not Tailwind's `ring-*` utility, so this doesn't depend on
                      Tailwind's internal --tw-ring-color implementation detail). */}
                  <div
                    className="pointer-events-none absolute inset-0 rounded-2xl opacity-0 transition-opacity duration-200 group-hover:opacity-100"
                    style={{ boxShadow: `inset 0 0 0 2px ${it.accent}` }}
                    aria-hidden
                  />
                  <div className="pointer-events-none absolute inset-x-0 bottom-0 h-2/3 bg-gradient-to-t from-black/90 to-transparent" />
                  {/* "Browse mods" reveal — the catalogue framing, not just a poster wall */}
                  <div className="pointer-events-none absolute inset-0 flex items-end justify-center pb-3 opacity-0 transition-opacity duration-200 group-hover:opacity-100">
                    <span
                      className="rounded-full px-3 py-1 text-[11px] font-semibold uppercase tracking-wide text-white"
                      style={{ background: it.accent }}
                    >
                      Browse mods →
                    </span>
                  </div>
                </div>
                <div className="p-3">
                  <p className="truncate text-sm font-semibold text-white">{it.name}</p>
                  <p className="text-[11px] text-slate-400">{it.count.toLocaleString()} mods</p>
                </div>
              </Link>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

import { GAME_ART_SLUG, GAME_DISPLAY, type GameFamily } from "@/lib/games";
import { getPosterAccentColor } from "@/lib/game-poster-color";
import { GameCatalogueCarousel, type CatalogueItem } from "./GameCatalogueCarousel";

/**
 * The NxLabs homepage's real "game catalogue" — every real family
 * `listCatalogFamilies()` returns (already the FULL set, not a "popular"
 * subset — see PopularGamesStrip.tsx's own comment, it renders the same
 * complete list at a compact size for the dashboard's tighter layout). This
 * is a bigger, more premium presentation of that same real data for the
 * marketing homepage specifically: full portrait box art (not a cropped
 * 4:3 thumbnail), a per-game accent ring genuinely sampled from that game's
 * own art (lib/game-poster-color.ts — same real-pixel method GameBadge
 * uses, never a hand-picked hex), and an explicit "Browse mods" reveal on
 * hover/focus so this reads as the catalogue's own front door rather than a
 * strip of tiles above the fold.
 *
 * Async Server Component: the accent-color sample is a cached, network-free
 * disk read (see getPosterAccentColor's own header comment), so resolving it
 * for every family up front costs nothing after the first render. All of
 * that stays server-side here; the search box and single-row sliding
 * carousel (both need client state) live in GameCatalogueCarousel.tsx, which
 * receives this fully-resolved, already-real data as plain props — a
 * function prop like `hrefFor` can't cross the server/client boundary, so
 * every family's real href is resolved into a plain string here instead.
 */
export async function GameCatalogueGrid({
  families,
  hrefFor,
}: {
  families: { family: string; label: string; count: number }[];
  hrefFor: (family: string) => string;
}) {
  const accents = await Promise.all(families.map((f) => getPosterAccentColor(f.family)));

  const items: CatalogueItem[] = families.map((f, i) => ({
    family: f.family,
    name: GAME_DISPLAY[f.family as GameFamily]?.name ?? f.label,
    count: f.count,
    poster: GAME_ART_SLUG[f.family as GameFamily]?.poster ?? GAME_ART_SLUG[f.family as GameFamily]?.hero,
    accent: accents[i],
    href: hrefFor(f.family),
  }));

  return <GameCatalogueCarousel items={items} />;
}
